#!/usr/bin/env bash
#
# A wizard walks a human through setting up and deploying CNtagram to Render,
# provisioning Managed PostgreSQL, configuring secrets, and testing backup/restore.
# Generated by the /wizard skill for Issue #139 (SP-4).
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit it.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

TOTAL_STAGES=0
_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env.render}"
WRITTEN_ENV=()
WRITTEN_SECRET=()
SKIPPED=()

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1
  fi
  printf '%s' "$value"
}

ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} )) && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

banner "CNtagram Production Deployment Wizard (SP-4 / Render)"

# ── Stage 1: Render Managed PostgreSQL Database ───────────────────────────
stage "Provision Managed PostgreSQL Database"
say "We will create a managed PostgreSQL instance in Singapore region."
open_url "https://dashboard.render.com"
step "1. In Render Dashboard, click 'New +' at the top right → select 'PostgreSQL'."
step "2. Name: cntagram-db"
step "3. Database: cntagram"
step "4. User: cntagram"
step "5. Region: Singapore (Southeast Asia)"
step "6. Instance Type: Free (or Hobby)"
step "7. Click 'Create Database' and wait until status is Available."
step "8. Copy the 'Internal Database URL' (for the web service) and 'External Database URL'."
ask_secret INTERNAL_DATABASE_URL "Paste the Internal Database URL (postgres://...):"
write_env DATABASE_URL "$INTERNAL_DATABASE_URL"
ask_secret EXTERNAL_DATABASE_URL "Paste the External Database URL (for local backup/restore tool):"
write_env EXTERNAL_DATABASE_URL "$EXTERNAL_DATABASE_URL"

# ── Stage 2: Web Service Setup ────────────────────────────────────────────
stage "Create Web Service on Render"
say "Now we connect your GitHub repository to a new Render Web Service."
open_url "https://dashboard.render.com/select-repo?type=web"
step "1. Connect your GitHub repository 'cntagram' (Jupiter4428/cntagram)."
step "2. Name: cntagram"
step "3. Region: Singapore (MUST match PostgreSQL region!)"
step "4. Branch: develop (or main)"
step "5. Runtime: Python 3"
step "6. Build Command: ./build.sh (or bash build.sh)"
step "7. Start Command: gunicorn portal.wsgi:application"
step "8. Auto-Deploy: Yes"
ask SERVICE_SLUG "Enter your service name/slug (e.g. cntagram):"
APP_HOSTNAME="${SERVICE_SLUG}.onrender.com"
write_env ALLOWED_HOSTS ".onrender.com,localhost,127.0.0.1"
write_env CSRF_TRUSTED_ORIGINS "https://*.onrender.com,https://${APP_HOSTNAME}"

# ── Stage 3: Environment Variables Configuration ──────────────────────────
stage "Configure Production Environment Variables"
say "Generate and configure production secrets for Render Web Service."
# Generate a cryptographically strong 50-character Django secret key if missing
DEFAULT_SECRET=$(python -c "import secrets; print(secrets.token_urlsafe(50))" 2>/dev/null || echo "django-prod-secret-$(date +%s)")
CURRENT_SECRET=$(_existing "SECRET_KEY" || echo "$DEFAULT_SECRET")
write_env SECRET_KEY "$CURRENT_SECRET"
write_env DEBUG "False"
ask DJANGO_SUPERUSER_EMAIL "Enter email for admin superuser (e.g. admin@example.com):"
write_env DJANGO_SUPERUSER_EMAIL "$DJANGO_SUPERUSER_EMAIL"
ask_secret DJANGO_SUPERUSER_PASSWORD "Enter desired password for admin superuser:"
write_env DJANGO_SUPERUSER_PASSWORD "$DJANGO_SUPERUSER_PASSWORD"

open_url "https://dashboard.render.com"
say "In Render Web Service → 'Environment' tab, add these Key-Value pairs:"
note "  - PYTHON_VERSION = 3.12.0"
note "  - DEBUG = False"
note "  - SECRET_KEY = (saved in your $ENV_FILE)"
note "  - DATABASE_URL = $INTERNAL_DATABASE_URL"
note "  - ALLOWED_HOSTS = .onrender.com,localhost,127.0.0.1"
note "  - CSRF_TRUSTED_ORIGINS = https://*.onrender.com"
note "  - DJANGO_SUPERUSER_EMAIL = $DJANGO_SUPERUSER_EMAIL"
note "  - DJANGO_SUPERUSER_PASSWORD = (entered above)"
pause "Press Enter after adding all environment variables in Render..."

# ── Stage 4: Verify Deployment and HTTPS ───────────────────────────────────
stage "Verify Live Deployment & HTTPS"
say "Wait for Render build and deployment to finish, then test the live URL."
open_url "https://${APP_HOSTNAME}"
step "1. In Render Dashboard → 'Events' & 'Logs', confirm build.sh ran successfully."
step "2. Check: Static files loaded with styling (CSS/JS present)."
step "3. Check: HTTPS padlock icon in browser address bar."
step "4. Open https://${APP_HOSTNAME}/admin/ and verify login with email '${DJANGO_SUPERUSER_EMAIL:-admin@example.com}'."
pause "Press Enter once you verified the live deployment..."

# ── Stage 5: Test Backup & Disaster Recovery ──────────────────────────────
stage "Test Daily Backup and Restore (AC Verification)"
say "We will test the database backup and restore routine using bash/pg_dump."
step "The script 'scripts/backup_restore.sh' performs an automated dump and restore test."
note "Running backup test now..."
if [[ -x "./scripts/backup_restore.sh" ]]; then
  ./scripts/backup_restore.sh test || warn "Run ./scripts/backup_restore.sh manually when DB is online"
else
  warn "Please run: bash scripts/backup_restore.sh test"
fi
confirm "Did the backup and restore verification test complete successfully?" || warn "Verify backup script logs before closing issue"

finish
}

run_wizard "$@"; exit

